window.HOEREN_TESTS[18] = {"id":"bank-und-geld","name":"Bank und Geld","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden der Sparkasse, eine Information: Unsere Filiale in der Marktstraße ist heute geschlossen wegen Renovierung. Sie können die Filiale in der Marktstraße also heute nicht besuchen. Nutzen Sie die nächste Filiale in der Bahnhofstraße oder den Online-Banking-Service. Geldautomaten funktionieren überall normal. Morgen sind wir wieder offen. Heute fehlt nur diese eine Filiale.","gender":"f","q":"Was ist heute möglich?","opts":["Online-Banking oder die andere Filiale nutzen.","Gar nichts.","Die Marktstraße-Filiale besuchen."],"correct":0},{"transcript":"Hallo Frau Schmidt, hier ist Ihre Bank. Wir wollten Sie informieren: Ihre EC-Karte funktioniert ab nächster Woche nicht mehr — die ist abgelaufen. Wir senden Ihnen die neue Karte per Post in den nächsten 5 Tagen. Bitte schauen Sie in Ihren Briefkasten und unterschreiben Sie die neue Karte sofort.","gender":"m","q":"Was bekommt Frau Schmidt?","opts":["Geld.","Eine neue Karte per Post.","Einen Termin."],"correct":1},{"transcript":"Hier ist die Steuerberatung Klein. Ihre Steuererklärung ist fertig — Sie bekommen 850 Euro zurück. Das Geld wird in den nächsten 3 Wochen auf Ihr Konto überwiesen. Falls Sie Fragen haben, rufen Sie uns gerne an. Unsere Rechnung für die Beratung — 180 Euro — bezahlen Sie wie üblich am Monatsende.","gender":"f","q":"Wie viel bekommt der Kunde von der Steuer zurück?","opts":["850 Euro.","180 Euro.","1030 Euro."],"correct":0},{"transcript":"Achtung, liebe Kunden im Wechselbüro. Heute haben wir gute Kurse für Dollar — 1 Euro entspricht 1 Dollar 10. Für britische Pfund ist der Kurs schlechter als letzte Woche, also nicht günstig. Schweizer Franken sind etwa gleich geblieben, auch nicht besser. Am günstigsten ist heute also der Dollar. Fragen Sie uns gern, wenn Sie unsicher sind.","gender":"m","q":"Was ist heute am günstigsten zum Tauschen?","opts":["Schweizer Franken.","Britische Pfund.","Dollar."],"correct":2},{"transcript":"Hallo Tom, hier ist Anna. Ich kann dir das geliehene Geld leider nicht diese Woche zurückgeben, wie geplant. Mein Auto musste in die Werkstatt — 600 Euro! Nächsten Monat ist zu spät, das möchte ich nicht. Aber spätestens nächste Woche, wenn mein Gehalt kommt, bekommst du alles. Bitte habe Geduld. Tut mir leid für die Verzögerung.","gender":"f","q":"Wann gibt Anna das Geld zurück?","opts":["Diese Woche wie geplant.","Nächste Woche.","Erst nächsten Monat."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer übernimmt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Markus","gender":"m","text":"Hallo Anna! Am Monatsanfang müssen wir die Zahlungen klar verteilen. Ich habe die Liste."},{"speaker":"Anna","gender":"f","text":"Leg sie auf den Tisch. Dann vergessen wir keine wichtige Zahlung in diesem Monat."},{"speaker":"Markus","gender":"m","text":"Ich zahle die Miete am Ersten. Das Geld geht direkt an den Vermieter."},{"speaker":"Anna","gender":"f","text":"Die Miete ist unser größter Posten. Sollen wir diese Woche auch die Steuern zahlen?"},{"speaker":"Markus","gender":"m","text":"Nein. Steuern zahlen wir jetzt nicht. Der Termin kommt erst im nächsten Monat."},{"speaker":"Anna","gender":"f","text":"Ich zahle die Stromrechnungen am selben Tag."},{"speaker":"Markus","gender":"m","text":"Die Stromrechnungen kommen diesmal per Post. Annas Mutter kennt die Kinderkonten gut."},{"speaker":"Anna","gender":"f","text":"Annas Mutter verwaltet das Sparkonto der Kinder. Sie legt jeden Monat etwas zurück."},{"speaker":"Markus","gender":"m","text":"Das Sparkonto wächst so langsam weiter. Annas Vater hat die Ordner im Schrank."},{"speaker":"Anna","gender":"f","text":"Annas Vater prüft die Versicherungen. Er schaut, ob der Vertrag noch passt."},{"speaker":"Markus","gender":"m","text":"Versicherungen soll man jedes Jahr ansehen. Kaufen wir Geschenke für die Familie?"},{"speaker":"Anna","gender":"f","text":"Geschenke kaufen wir diesen Monat nicht. Das Geld ist schon ziemlich knapp."},{"speaker":"Markus","gender":"m","text":"Lisa übernimmt am Samstag den Markt."},{"speaker":"Anna","gender":"f","text":"Lisa macht den Lebensmittel-Einkauf. Milch und Brot holt sie immer samstags dort."},{"speaker":"Markus","gender":"m","text":"Einverstanden. Ich lege die Liste neben den Computer. Bis zum Ersten."}],"options":[{"letter":"a","text":"macht den Lebensmittel-Einkauf"},{"letter":"b","text":"verwaltet das Online-Banking"},{"letter":"c","text":"verwaltet das Sparkonto der Kinder"},{"letter":"d","text":"zahlt Steuern"},{"letter":"e","text":"zahlt die Stromrechnungen"},{"letter":"f","text":"kauft Geschenke für die Familie"},{"letter":"g","text":"prüft die Versicherungen"},{"letter":"h","text":"zahlt die Miete"},{"letter":"i","text":"kümmert sich um die Bank-Karten"}],"items":[{"person":"Markus","correct":"h"},{"person":"Anna","correct":"e"},{"person":"Annas Mutter","correct":"c"},{"person":"Annas Vater","correct":"g"},{"person":"Lisa","correct":"a"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Bank-Beraterin","gender":"f","text":"Guten Tag, wie kann ich Ihnen helfen?"},{"speaker":"Kunde","gender":"m","text":"Ich möchte ein Konto eröffnen. Was haben Sie — Standard oder Premium?"},{"speaker":"Bank-Beraterin","gender":"f","text":"Wir haben Standard-Konto kostenlos, Premium-Konto 5 Euro pro Monat. Premium hat mehr Leistungen. Sie müssen kein Konto eröffnen."},{"speaker":"Kunde","gender":"m","text":"Premium brauche ich nicht. Standard reicht mir, ich nutze die Bank nicht oft."},{"speaker":"Bank-Beraterin","gender":"f","text":"Gerne, dann das kostenlose Standard-Konto. Ich bereite die Papiere vor."}],"q":"Welches Konto wählt der Kunde?","opts":["Standard-Konto kostenlos.","Premium-Konto 5 Euro.","Er nimmt kein Konto."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, mein Geld ist nicht angekommen! Soll ich die Polizei rufen?"},{"speaker":"Bank-Mitarbeiter","gender":"m","text":"Welche Überweisung fehlt denn? Wir schauen zuerst in der Bank, nicht sofort zur Polizei."},{"speaker":"Kundin","gender":"f","text":"Mein Gehalt vom 25. — heute ist der 28. und nichts. Soll ich schon einen Antrag stellen?"},{"speaker":"Bank-Mitarbeiter","gender":"m","text":"Manche Überweisungen brauchen 3 bis 5 Werktage. Schauen Sie morgen nochmal. Kein Antrag und keine Polizei heute."},{"speaker":"Kundin","gender":"f","text":"Okay, ich warte bis morgen. Wenn es dann fehlt, komme ich wieder."}],"q":"Was soll die Kundin tun?","opts":["Sofort die Polizei rufen.","Sofort einen Antrag stellen.","Bis morgen warten."],"correct":2},{"lines":[{"speaker":"Verkäufer","gender":"m","text":"Wie zahlen Sie bitte? Mit Karte oder bar?"},{"speaker":"Kundin","gender":"f","text":"Mit Karte, das ist einfacher. Ich kaufe die Sachen auf jeden Fall."},{"speaker":"Verkäufer","gender":"m","text":"Tut mir leid, unser Kartenleser ist heute kaputt. Nur Bar möglich, Karte geht nicht."},{"speaker":"Kundin","gender":"f","text":"Bar habe ich nicht so viel. Ich gehe zum Geldautomaten und komme zurück, dann zahle ich bar."},{"speaker":"Verkäufer","gender":"m","text":"Kein Problem, ich lege die Ware kurz zur Seite."}],"q":"Wie zahlt die Kundin am Ende?","opts":["Mit Karte.","Bar, nach dem Geldautomaten.","Sie kauft nicht."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Schatz, ich möchte mein Sparbuch sehen. Wo prüfe ich mein Geld am besten?"},{"speaker":"Tochter","gender":"f","text":"Du hast doch eine App auf dem Handy. Im Internet geht es auch."},{"speaker":"Vater","gender":"m","text":"Ich vertraue der App nicht, und das Internet ist unsicher. Ich gehe lieber zur Filiale und schaue die Zahlen auf dem Papier."},{"speaker":"Tochter","gender":"f","text":"Wie du willst, Papa. In der Filiale erklären sie dir alles."},{"speaker":"Vater","gender":"m","text":"Genau, dann gehe ich nachher zur Bank."}],"q":"Wo prüft der Vater sein Geld?","opts":["In der App.","Im Internet.","In der Bank-Filiale."],"correct":2},{"lines":[{"speaker":"Freund","gender":"m","text":"Kannst du mir 50 Euro leihen? Ich gebe sie nächste Woche zurück, ehrlich."},{"speaker":"Freundin","gender":"f","text":"50 Euro sind viel, das leihe ich nicht. 20 Euro ist okay. Nichts leihen möchte ich auch nicht, du bist mein Freund."},{"speaker":"Freund","gender":"m","text":"20 reicht eigentlich nicht ganz. Aber okay, dann 20, besser als nichts."},{"speaker":"Freundin","gender":"f","text":"Hier sind 20 Euro. Bitte nächste Woche zurück, nicht später."},{"speaker":"Freund","gender":"m","text":"Klar, danke dir. Nächste Woche bekommst du sie."}],"q":"Wie viel leiht die Freundin?","opts":["50 Euro.","20 Euro.","Sie leiht nichts."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Lehmann, einem Bank-Berater. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Lehmann, Sie arbeiten seit 22 Jahren als Bank-Berater. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Lehmann","gender":"m","text":"Eigentlich wollte ich Wirtschaftslehrer werden. Aber während meines Studiums habe ich ein Praktikum in einer Bank gemacht — das war so spannend, ich habe direkt nach dem Studium angefangen. Jetzt bin ich schon ewig dabei."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie typischerweise?"},{"speaker":"Lehmann","gender":"m","text":"Kunden beraten zu Krediten, Sparen, Investitionen. Manche Kunden kommen täglich vorbei, manche einmal im Jahr. Ich helfe ihnen, gute Entscheidungen zu treffen. Manchmal muss ich auch ‚Nein‘ sagen, wenn ein Kredit zu riskant wäre."},{"speaker":"Reporter","gender":"m","text":"Hat sich Ihr Beruf verändert?"},{"speaker":"Lehmann","gender":"m","text":"Sehr. Vor 20 Jahren kamen alle in die Filiale. Heute machen viele alles online — vor allem die Jüngeren. Wir Berater treffen nur noch komplizierte Fälle: Hauskauf, große Investitionen. Einfache Sachen sind weg."},{"speaker":"Reporter","gender":"m","text":"Mögen Sie das?"},{"speaker":"Lehmann","gender":"m","text":"Gemischt. Die einfachen Gespräche fehlen mir — da gab es viele schöne menschliche Momente. Aber die komplizierten Beratungen sind interessanter. Es ist mehr Verantwortung."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie selbst mit Ihrem Geld?"},{"speaker":"Lehmann","gender":"m","text":"Ich spare regelmäßig — wenig, aber jeden Monat. Ich investiere konservativ, kein Risiko. Auch wenn ich anderen rate, Risiko zu nehmen, mache ich es selbst nicht. Ich bin vorsichtig."}],"items":[{"q":"Herr Lehmann wollte ursprünglich Lehrer werden.","correct":"ja"},{"q":"Heute kommen viele Kunden online statt in die Filiale.","correct":"ja"},{"q":"Die einfachen Gespräche mit Kunden sind heute noch wie früher.","correct":"nein"},{"q":"Privat investiert er sehr risikoreich.","correct":"nein"},{"q":"Er spart jeden Monat etwas Geld.","correct":"ja"}]}]};
